import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.DuVOYUUM.js";const d=JSON.parse('{"title":"Native Install","description":"","frontmatter":{},"headers":[],"relativePath":"projects/igvc-2026/software/environment-setup/native.md","filePath":"projects/igvc-2026/software/environment-setup/native.md","lastUpdated":1790647345000}'),r={name:"projects/igvc-2026/software/environment-setup/native.md"};function l(i,e,n,u,h,p){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="native-install" tabindex="-1">Native Install <a class="header-anchor" href="#native-install" aria-label="Permalink to &quot;Native Install&quot;">​</a></h1><h2 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to &quot;Ubuntu&quot;">​</a></h2><p>ROS 2 has a variety of <a href="https://docs.ros.org/en/jazzy/Releases.html" target="_blank" rel="noreferrer">distributions</a> which support <a href="https://reps.openrobotics.org/rep-2000/#jazzy-jalisco-may-2024---may-2029" target="_blank" rel="noreferrer">targeted operating systems</a> at various levels. We recommend to only use the &quot;Tier 1&quot; supported operating systems as they receive the most support and typically work out of the box.</p><p>Since we are using <strong>ROS 2 Jazzy</strong>, we recommend installing <strong>Ubuntu 24.04</strong>, which is a Tier 1 supported OS and allows ROS to be installed and maintained entirely via Debian packages.</p><ol><li>Download the Ubuntu 24.04 ISO <a href="https://ubuntu.com/download/desktop" target="_blank" rel="noreferrer">here.</a></li><li>Make a bootable USB with the ISO. <ul><li><a href="https://rufus.ie/en/" target="_blank" rel="noreferrer">Rufus</a></li><li><a href="https://etcher.balena.io/" target="_blank" rel="noreferrer">Balena Etcher</a></li></ul></li><li><a href="https://ubuntu.com/tutorials/install-ubuntu-desktop#1-overview" target="_blank" rel="noreferrer">Install Ubuntu Desktop</a></li><li><a href="#ros-2">Install ROS 2</a></li></ol><h2 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h2><ol><li><a href="https://docs.ros.org/en/jazzy/Installation/Ubuntu-Install-Debians.html" target="_blank" rel="noreferrer">Install ROS 2 Jazzy</a><ul><li>Be sure to do the full desktop install (<code>sudo apt install ros-jazzy-desktop</code>).</li><li>Install Ros 2 optional tools (needed for workspace setup)(<code>sudo apt install ros-dev-tools</code>)</li><li>To verify that your installation works correctly, try running the ROS 2 talker/listener examples from the official documentation.</li></ul></li><li>Run this command:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;source /opt/ros/jazzy/setup.bash&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre></div>This will make it so the <code>source</code> command will be run for you automatically every time you open a new terminal.<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you are running a different shell (e.g., zsh), you will need to source the corresponding setup file to the correct shell configuration file</p></div></li></ol>',7)]))}const f=t(r,[["render",l]]);export{d as __pageData,f as default};
